<?php /* * ========================================================= * api/get_private.php * * Получение приватного диалога. * * PHP 5.6.4 * * Логика: * * is_read = 0 -> непрочитано * is_read = 1 -> прочитано * * При открытии диалога сообщения от собеседника * текущему пользователю помечаются прочитанными. * ========================================================= */ require_once __DIR__ . '/../config/auth.php'; requireLogin(); checkBlocked(); updateLastActivity(); header('Content-Type: application/json; charset=utf-8'); /* * ========================================================= * ТЕКУЩИЙ ПОЛЬЗОВАТЕЛЬ * ========================================================= */ $myId = (int) currentUserId(); /* * ========================================================= * СОБЕСЕДНИК * ========================================================= */ $targetId = isset($_GET['user_id']) ? (int) $_GET['user_id'] : 0; if ( $targetId <= 0 || $targetId === $myId ) { echo json_encode( array(), JSON_UNESCAPED_UNICODE ); exit; } /* * ========================================================= * ПРОВЕРЯЕМ СОБЕСЕДНИКА * ========================================================= */ $stmt = $pdo->prepare( 'SELECT id, username FROM users WHERE id = ? LIMIT 1' ); $stmt->execute( array( $targetId ) ); $targetUser = $stmt->fetch(); if (!$targetUser) { echo json_encode( array(), JSON_UNESCAPED_UNICODE ); exit; } /* * ========================================================= * ПОЛУЧАЕМ СООБЩЕНИЯ * ========================================================= */ $stmt = $pdo->prepare( 'SELECT pm.id, pm.sender_id, pm.receiver_id, pm.message, pm.created_at, sender.username AS sender_name, receiver.username AS receiver_name FROM private_messages pm LEFT JOIN users sender ON sender.id = pm.sender_id LEFT JOIN users receiver ON receiver.id = pm.receiver_id WHERE ( pm.sender_id = ? AND pm.receiver_id = ? ) OR ( pm.sender_id = ? AND pm.receiver_id = ? ) ORDER BY pm.id ASC LIMIT 100' ); $stmt->execute( array( $myId, $targetId, $targetId, $myId ) ); $messages = $stmt->fetchAll(); /* * ========================================================= * ПОМЕЧАЕМ ОСНОВНЫЕ СООБЩЕНИЯ ПРОЧИТАННЫМИ * * ВАЖНО: * * Только сообщения: * * targetId -> myId * * То есть только входящие сообщения текущему * пользователю от открытого собеседника. * * Уже прочитанные записи не трогаем. * ========================================================= */ $stmt = $pdo->prepare( 'UPDATE private_messages SET is_read = 1 WHERE sender_id = ? AND receiver_id = ? AND is_read = 0' ); $stmt->execute( array( $targetId, $myId ) ); /* * ========================================================= * ПОМЕЧАЕМ АРХИВНЫЕ ЛИЧНЫЕ СООБЩЕНИЯ ПРОЧИТАННЫМИ * * Именно эта таблица используется для unread_count. * * Поэтому здесь обязательно: * * sender_id = собеседник * receiver_id = текущий пользователь * is_read = 0 * * Только такие записи меняем на 1. * ========================================================= */ $stmt = $pdo->prepare( 'UPDATE personal_messages SET is_read = 1 WHERE sender_id = ? AND receiver_id = ? AND is_read = 0' ); $stmt->execute( array( $targetId, $myId ) ); /* * ========================================================= * ВОЗВРАЩАЕМ СООБЩЕНИЯ * ========================================================= */ echo json_encode( $messages, JSON_UNESCAPED_UNICODE ); exit; ?>